// secretshare — Shamir's Secret Sharing over GF(256)

fn gf_mul::(a, b) {
    let mut p = 0;
    let mut aa = a;
    let mut bb = b;
    for i in @range(0, 8) {
        if ((bb & 1) != 0) { p = p ^ aa; }
        let hi = aa & 128;
        aa = (aa << 1) & 255;
        if (hi != 0) { aa = aa ^ 27; }
        bb = bb >> 1;
    }
    return p;
}

fn gf_inv::(a) {
    if (a == 0) { @raise("secretshare: inverse of zero"); }
    let mut r = 1;
    for i in @range(0, 254) { r = gf_mul(r, a); }
    return r;
}

fn poly_eval::(coeffs, x) {
    let mut y = 0;
    let mut power = 1;
    for i in @range(0, @len(coeffs)) {
        y = y ^ gf_mul(coeffs[i], power);
        power = gf_mul(power, x);
    }
    return y;
}

fn split_secret::(secret_b64, n, k) {
    if (k > n) { @raise("secretshare: k must be <= n"); }
    let secret = @base64_decode(secret_b64);
    let shares = [];
    for i in @range(0, n) { @push(shares, []); }
    for b_idx in @range(0, @len(secret)) {
        let coeffs = [secret[b_idx]];
        for i in @range(1, k) { @push(coeffs, @crypto_random_int(1, 255)); }
        for x in @range(1, n + 1) { @push(shares[x - 1], poly_eval(coeffs, x)); }
    }
    let out = [];
    for i in @range(0, n) {
        @push(out, {"x": i + 1, "y": @base64(@bytes(shares[i]))});
    }
    return out;
}

fn combine_shares::(shares) {
    if (@len(shares) < 2) { @raise("secretshare: need 2+ shares"); }
    let max_len = 0;
    let ys = [];
    for s in shares {
        let y = @base64_decode(s["y"]);
        @push(ys, y);
        if (@len(y) > max_len) { max_len = @len(y); }
    }
    let result = [];
    for b_idx in @range(0, max_len) {
        let secret_byte = 0;
        for i in @range(0, @len(shares)) {
            let xi = shares[i]["x"];
            let yi = ys[i][b_idx];
            let num = 1;
            let den = 1;
            for j in @range(0, @len(shares)) {
                if (i == j) { continue; }
                let xj = shares[j]["x"];
                num = gf_mul(num, xj);
                den = gf_mul(den, xi ^ xj);
            }
            secret_byte = secret_byte ^ gf_mul(yi, gf_mul(num, gf_inv(den)));
        }
        @push(result, secret_byte);
    }
    return @base64(@bytes(result));
}

fn version::() { return "1.0.0"; }
